SINA_SMART["pharma-biotransformation"] = {"lecture":"pharma-biotransformation","title":"Biotransformation (drug metabolism)","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"pharma-biotransformation:e0","text":"Metabolism outcomes: deactivation, prodrug activation, detoxification, toxification, solubility change.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"pharma-biotransformation:e1","text":"First-pass metabolism affects oral (and partly rectal) drugs.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"pharma-biotransformation:e2","text":"Phase I: CYP450 oxidation, reduction, hydrolysis. Phase II: conjugation.","topic":"Phase I and phase II","sec":1,"importance":"core","highYield":"untested"},{"id":"pharma-biotransformation:e3","text":"CYP450 lives in the smooth ER; needs NADPH, P450 reductase and O₂.","topic":"Cytochrome P450","sec":2,"importance":"core","highYield":"untested"},{"id":"pharma-biotransformation:e4","text":"CYP3A4 handles 50-60% of drugs; inhibited by grapefruit juice.","topic":"Cytochrome P450","sec":2,"importance":"core","highYield":"untested"},{"id":"pharma-biotransformation:e5","text":"CYP2D6 ≈ 25% of drugs; inhibited by quinidine, fluoxetine, paroxetine.","topic":"Cytochrome P450","sec":2,"importance":"core","highYield":"untested"},{"id":"pharma-biotransformation:e6","text":"Inducers: rifampin, phenytoin, carbamazepine, barbiturates, St John's wort.","topic":"Induction, inhibition and liver disease","sec":3,"importance":"core","highYield":"untested"},{"id":"pharma-biotransformation:e7","text":"Inhibitors: erythromycin, ketoconazole, cimetidine, fluoxetine, quinidine.","topic":"Induction, inhibition and liver disease","sec":3,"importance":"core","highYield":"untested"},{"id":"pharma-biotransformation:e10","text":"Warfarin dose varies 20×: VKORC1 > CYP2C9.","topic":"Pharmacogenetics","sec":4,"importance":"core","highYield":"untested"},{"id":"pharma-biotransformation:e8","text":"Codeine → morphine needs CYP2D6: poor metabolisers get no analgesia.","topic":"Pharmacogenetics","sec":4,"importance":"core","highYield":"untested"},{"id":"pharma-biotransformation:e9","text":"Tamoxifen + fluoxetine: loss of tamoxifen activation.","topic":"Pharmacogenetics","sec":4,"importance":"core","highYield":"untested"},{"id":"pharma-biotransformation:e11","text":"NAT2 slow acetylators: isoniazid, hydralazine, procainamide, dapsone.","topic":"Non-CYP oxidation, conjugation and hydrolysis","sec":5,"importance":"core","highYield":"untested"},{"id":"pharma-biotransformation:e12","text":"Plasma cholinesterase deficiency: prolonged succinylcholine paralysis.","topic":"Non-CYP oxidation, conjugation and hydrolysis","sec":5,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"15ym087":"a","1ajb846":"a","1a4m43u":"a","1avv3f8":"a","1n6wg6c":"a","6l6qnx":"a","qe19yg":"a","1i9yslo":"a","96yvyn":"a","1skvocu":"a","zpuntt":"a","141pmy":"a","1tz741l":"a","y8s4se":"a","zu7cl5":"a","1y7ddxp":"a","1rstgvf":"a","1sc5x1m":"a","bgsoxf":"x"},"mapCounts":{"verified":0,"auto":18,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"pharma-biotransformation:e0":{"s":0,"u":["Metabolism outcomes: deactivation, prodrug activation, detoxification, toxification, solubility change.","Metabolism has five possible outcomes: deactivation (most drugs), activation of a prodrug , detoxification , toxification (rare: paracetamol) and a change of solubility (lipophilic → hydrophilic)."],"dp":[]},"pharma-biotransformation:e1":{"s":0,"u":["First-pass metabolism affects oral (and partly rectal) drugs.","The liver is the main site; drugs given orally (and partly rectally) undergo first-pass metabolism in the gut wall and liver, reducing bioavailability."],"dp":[]},"pharma-biotransformation:e2":{"s":1,"u":["Phase I: CYP450 oxidation, reduction, hydrolysis. Phase II: conjugation.","Phase I (oxidation, reduction, hydrolysis) introduces or unmasks a functional group (-OH, -NH₂, -SH), mostly via cytochrome P450 ; the product may be excreted if polar enough.","Some drugs use only one phase, both, other systems, or are excreted unchanged."],"dp":[]},"pharma-biotransformation:e3":{"s":2,"u":["CYP450 lives in the smooth ER; needs NADPH, P450 reductase and O₂.","A haem at the active site performs the redox reaction with NADPH-P450 oxidoreductase , NADPH and O₂: the Fe³⁺ P450 binds the drug, receives two electrons, activates oxygen and oxidises the drug."],"dp":[]},"pharma-biotransformation:e4":{"s":2,"u":["CYP3A4 handles 50-60% of drugs; inhibited by grapefruit juice.","Six main enzymes (≈90% of xenobiotic metabolism) : 1A2 (aromatic hydrocarbons, methylxanthines), 2C9 (S-warfarin, phenytoin), 2C19 (proton pump inhibitors in part, carisoprodol), 2D6 (about 25% of drugs: many cardiac and psychiatric drugs; strongly inhibited by quinidine, fluoxetine, paroxetine), 2E1 (paracetamol, high-dose ethanol, halogenated hydrocarbons; centrilobular), 3A4 (most liver and gut-wall CYP, first-pass; 50-60% of all drugs : calcium channel blockers, steroids, statins, benzodiazepines; inhibited by grapefruit juice; induction shared with P-glycoprotein)."],"dp":[{"h":"Why grapefruit juice can double a statin's level","t":"CYP3A4 in the gut wall normally destroys a large part of an oral dose before it reaches the blood. Grapefruit compounds irreversibly inhibit that intestinal CYP3A4, so much more drug gets through. The effect lasts until new enzyme is made, which is why simply spacing the juice and the tablet does not fully help. Source: the lecture's CYP3A4 slide."}]},"pharma-biotransformation:e5":{"s":2,"u":["CYP2D6 ≈ 25% of drugs; inhibited by quinidine, fluoxetine, paroxetine.","Six main enzymes (≈90% of xenobiotic metabolism) : 1A2 (aromatic hydrocarbons, methylxanthines), 2C9 (S-warfarin, phenytoin), 2C19 (proton pump inhibitors in part, carisoprodol), 2D6 (about 25% of drugs: many cardiac and psychiatric drugs; strongly inhibited by quinidine, fluoxetine, paroxetine), 2E1 (paracetamol, high-dose ethanol, halogenated hydrocarbons; centrilobular), 3A4 (most liver and gut-wall CYP, first-pass; 50-60% of all drugs : calcium channel blockers, steroids, statins, benzodiazepines; inhibited by grapefruit juice; induction shared with P-glycoprotein)."],"dp":[]},"pharma-biotransformation:e6":{"s":3,"u":["Inducers: rifampin, phenytoin, carbamazepine, barbiturates, St John's wort.","Inducers speed metabolism (the drug's own or others'): rifampin, phenytoin, carbamazepine, barbiturates, St John's wort ; smoking induces CYP1A, ethanol and ketones induce CYP2E1."],"dp":[]},"pharma-biotransformation:e7":{"s":3,"u":["Inhibitors: erythromycin, ketoconazole, cimetidine, fluoxetine, quinidine.","Inhibitors slow metabolism (competitive binding to haem, etc.): erythromycin, ketoconazole, cimetidine, fluoxetine, quinidine , grapefruit juice."],"dp":[]},"pharma-biotransformation:e10":{"s":4,"u":["Warfarin dose varies 20×: VKORC1 > CYP2C9.","Warfarin : doses vary 20-fold (0.5 to 10 mg/day); most variation comes from VKORC1 (the target enzyme; the 1639G>A variant increases sensitivity), with CYP2C9 variants also contributing; the risk is haemorrhage."],"dp":[]},"pharma-biotransformation:e8":{"s":4,"u":["Codeine → morphine needs CYP2D6: poor metabolisers get no analgesia.","Codeine needs CYP2D6 to become morphine: poor metabolisers get no analgesia, ultra-rapid metabolisers risk opioid overdose.","CYP2D6 : over 50 alleles; about 8% of Caucasians and 0-2% of Asians are poor metabolisers; 3% of Spaniards and 13% of Ethiopians are ultra-rapid."],"dp":[{"h":"Why the same codeine dose can do nothing or be dangerous","t":"Codeine itself barely binds opioid receptors; its effect depends on conversion to morphine by CYP2D6. A poor metaboliser makes almost no morphine and gets no relief, while someone with duplicated CYP2D6 genes makes morphine fast enough to cause sedation and respiratory depression. Genotype, not dose alone, decides the result. Source: the lecture's codeine and CYP2D6 slides."}]},"pharma-biotransformation:e9":{"s":4,"u":["Tamoxifen + fluoxetine: loss of tamoxifen activation.","Tamoxifen is activated by 2D6 to 4-hydroxy-tamoxifen, so poor metabolisers and patients on fluoxetine or quinidine may lose its benefit."],"dp":[]},"pharma-biotransformation:e11":{"s":5,"u":["NAT2 slow acetylators: isoniazid, hydralazine, procainamide, dapsone.","Phase II : glucuronidation (UGT1 and UGT2; UGT1A1 polymorphism causes Gilbert's syndrome ), sulfation (SULT1, SULT2), glutathione conjugation (detoxifies reactive P450 metabolites such as paracetamol's), acetylation by N-acetyltransferases: NAT1 (PABA, sulphonamides), NAT2 (isoniazid, hydralazine, procainamide, dapsone), polymorphic: about 70% of Middle Eastern, 50% of Caucasian and 25% of Asian people are slow acetylators with higher drug levels."],"dp":[]},"pharma-biotransformation:e12":{"s":5,"u":["Plasma cholinesterase deficiency: prolonged succinylcholine paralysis.","Hydrolysis by esterases; plasma cholinesterase deficiency causes prolonged paralysis after succinylcholine ."],"dp":[]}},"meta":{"15ym087":{"a":"recall","vg":"pharma-biotransformation:e0/recall/1"},"1ajb846":{"a":"recall","vg":"pharma-biotransformation:e1/recall/1"},"1a4m43u":{"a":"recall","vg":"pharma-biotransformation:e3/recall/1"},"1avv3f8":{"a":"recall","vg":"pharma-biotransformation:e3/recall/2"},"1n6wg6c":{"a":"recall","vg":"pharma-biotransformation:e4/recall/1"},"6l6qnx":{"a":"recall","vg":"pharma-biotransformation:e4/recall/2"},"qe19yg":{"a":"recall","vg":"pharma-biotransformation:e10/recall/1"},"1i9yslo":{"a":"recall","vg":"pharma-biotransformation:e6/recall/1"},"96yvyn":{"a":"recall","vg":"pharma-biotransformation:e6/recall/2"},"1skvocu":{"a":"relationship","vg":"pharma-biotransformation:e8/relationship/1"},"zpuntt":{"a":"recall","vg":"pharma-biotransformation:e8/recall/1"},"141pmy":{"a":"application","vg":"pharma-biotransformation:e9/application/1"},"1tz741l":{"a":"recall","vg":"pharma-biotransformation:e10/recall/2"},"y8s4se":{"a":"recall","vg":"pharma-biotransformation:e8/recall/2"},"zu7cl5":{"a":"recall","vg":"pharma-biotransformation:e11/recall/1"},"1y7ddxp":{"a":"recall","vg":"pharma-biotransformation:e11/recall/2"},"1rstgvf":{"a":"recall","vg":"pharma-biotransformation:e11/recall/3"},"1sc5x1m":{"a":"recall","vg":"pharma-biotransformation:e12/recall/1"}},"explRev":"866bde8f80c8"};
